  public isDbConnected(alias: string = "default"): boolean {
    const conn = this.connections[alias];
    if (conn && "readyState" in conn) {
      return (conn as any).readyState === 1;
    }
    if (conn && "ended" in conn) {
      return !(conn as any).ended;
    }
    return !!conn;
  }

